package com.gregtech.gregtech.registry;
import com.gregtech.gregtech.block.misc.SpikeBlock;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.neoforged.neoforge.registries.DeferredHolder;
public final class GTSpikes {private GTSpikes(){}private static final java.util.Map<SpikeBlock.Family,DeferredHolder<Block,SpikeBlock>> ALL=new java.util.EnumMap<>(SpikeBlock.Family.class);public static SpikeBlock get(SpikeBlock.Family family){return ALL.get(family).get();}public static java.util.Collection<DeferredHolder<Block,SpikeBlock>> all(){return java.util.List.copyOf(ALL.values());}public static void initialize(){for(var family:SpikeBlock.Family.values()){String id="spike_"+family.name().toLowerCase(java.util.Locale.ROOT);var b=GTBlocks.BLOCKS.register(id,()->new SpikeBlock(family,BlockBehaviour.Properties.of().mapColor(MapColor.METAL).strength(30,5).requiresCorrectToolForDrops().sound(SoundType.METAL)));ALL.put(family,b);GTBlocks.BLOCK_ITEMS.register(id,()->new net.minecraft.world.item.BlockItem(b.get(),new net.minecraft.world.item.Item.Properties()));}}}
